using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Axpense.Api.Data; using Axpense.Api.Domain;
namespace Axpense.Api.Controllers;
[ApiController][Route("api/vehicles")] public class VehiclesController(AxpenseDbContext db):ControllerBase { [HttpGet] public async Task<IActionResult> Get(Guid organizationId)=>Ok(await db.Vehicles.AsNoTracking().Where(x=>x.OrganizationId==organizationId).OrderBy(x=>x.PlateNumber).ToListAsync()); [HttpGet("{id:guid}")] public async Task<IActionResult> GetById(Guid id)=>await db.Vehicles.FindAsync(id) is { } v?Ok(v):NotFound(); [HttpPost] public async Task<IActionResult> Create(CreateVehicleRequest r){if(!await db.Organizations.AnyAsync(x=>x.Id==r.OrganizationId))return BadRequest("Organization not found.");if(await db.Vehicles.AnyAsync(x=>x.OrganizationId==r.OrganizationId&&x.PlateNumber==r.PlateNumber))return Conflict("Plate number already exists in this organization.");var v=new Vehicle{OrganizationId=r.OrganizationId,PlateNumber=r.PlateNumber.Trim(),Make=r.Make.Trim(),Model=r.Model.Trim(),ModelYear=r.ModelYear,Vin=r.Vin,PurchasePrice=r.PurchasePrice,PurchaseDate=r.PurchaseDate,CurrentOdometer=r.CurrentOdometer,ExpectedResidualValue=r.ExpectedResidualValue,Status=string.IsNullOrWhiteSpace(r.Status)?"Active":r.Status,Notes=r.Notes};db.Vehicles.Add(v);await db.SaveChangesAsync();return Created($"/api/vehicles/{v.Id}",v);} [HttpPut("{id:guid}")] public async Task<IActionResult> Update(Guid id,UpdateVehicleRequest r){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();v.PlateNumber=r.PlateNumber.Trim();v.Make=r.Make.Trim();v.Model=r.Model.Trim();v.ModelYear=r.ModelYear;v.Vin=r.Vin;v.PurchasePrice=r.PurchasePrice;v.PurchaseDate=r.PurchaseDate;v.CurrentOdometer=r.CurrentOdometer;v.ExpectedResidualValue=r.ExpectedResidualValue;v.Status=r.Status;v.Notes=r.Notes;await db.SaveChangesAsync();return Ok(v);} [HttpDelete("{id:guid}")] public async Task<IActionResult> Delete(Guid id){var v=await db.Vehicles.FindAsync(id);if(v is null)return NotFound();db.Vehicles.Remove(v);await db.SaveChangesAsync();return NoContent();} }
public record CreateVehicleRequest(Guid OrganizationId,string PlateNumber,string Make,string Model,int ModelYear,string? Vin,decimal? PurchasePrice,DateTime? PurchaseDate,decimal? CurrentOdometer,decimal? ExpectedResidualValue,string? Status,string? Notes); public record UpdateVehicleRequest(string PlateNumber,string Make,string Model,int ModelYear,string? Vin,decimal? PurchasePrice,DateTime? PurchaseDate,decimal? CurrentOdometer,decimal? ExpectedResidualValue,string Status,string? Notes);
